select
gp.*
from groupon_promotion gp
left join groupon_promotion_item gpi on gp.groupon_promotion_id = gpi.groupon_promotion_id
left join product p on gpi.product_id = p.product_id


        and gp.name like concat('%', #{pageQuery.grouponName}, '%')


        and p.name like concat('%', #{pageQuery.productName}, '%')


        and p.product_sn like concat('%', #{pageQuery.productSn}, '%')


        and gp.shop_id = #{pageQuery.shopId}


        and gp.group_type = #{pageQuery.groupType}


        and #{pageQuery.searchStatusTime} >= gp.start_time
        and #{pageQuery.searchStatusTime} <= gp.end_time


        and gp.end_time < #{pageQuery.searchStatusTime}


        and gp.start_time > #{pageQuery.searchStatusTime}


        and gp.start_time <= #{pageQuery.endTime}


        and gp.end_time >= #{pageQuery.startTime}


GROUP BY gp.groupon_promotion_id

select
gp.*
from groupon_promotion gp
